				slot: p.slot,
				name: pagePresenceName(member.displayName, member.email),
				avatarUrl: pagePresenceAvatar(ctx.db.user.identity.find(ctx.sender)?.avatarUrl),
				pagePath: p.pagePath,
				anchor: p.anchor,
				anchorX: p.anchorX,
				anchorY: p.anchorY,
				pointX: p.pointX,
				pointY: p.pointY,
				clickSeq: p.clickSeq,
				activity: p.activity,
				updatedAt: ctx.timestamp
